Let $1\leq n\leq 6$, and let the initial datum $E_0 \subset \mathbb R^{n+1}$ be any bounded set of finite perimeter with $\mathcal{L}^{n+1}(\partial E_0)=0$. Then, for every flat flow $E_t$ obtained from the
minimizing-movements scheme and varifolds  $V_t$ obtained as above, the couple $(\{E_t\},\{V_t\})$ is a generalized BV flow. Specifically,  $\{V_t\}_{t\geq0}$ is an integral Brakke flow with
\begin{align}
|D\chi_{E_0}| = \|V_0\| &= \lim_{t \to 0^+} \|V_t\|\,, \label{intro:initial} \\
 |D\chi_{E_t}| &\le \|V_t\| \quad\qquad\text{for a.e. }t>0\,, \label{intro:domination}\\
 \partial\llbracket E_t \rrbracket &= [V_t] \quad\quad\quad \,\text{in the sense of currents $\mathrm{mod}(2)$, for a.e. $t > 0$}\,, \label{intro:comp}
\end{align}      
and the sets $E_t$ satisfy the following evolution law:  for every $0\leq s<t$ and every smooth compactly supported
test function $\phi=\phi(x,\tau)$,
\begin{equation}\label{intro:gen-BV}
    \int_{E_t}\phi(x,t)\,dx
    -
    \int_{E_s}\phi(x,s)\,dx
    =
    \int_s^t\int_{E_\tau}
    \partial_\tau\phi(x,\tau)\,dx\,d\tau
    +
    \int_s^t\int_{\partial^*E_\tau}
    \phi(x,\tau)\,
    \mathbf{H}_{V_\tau}\cdot\nu_{E_\tau}\,
    d\mathcal{H}^n\,d\tau \,,
\end{equation}
where $\mathbf H_{V_t}$ is generalized mean curvature vector of the varifold $V_t$.

\label{lem:reg}
If $1\leq n\leq6$, every nonempty iterate $E^h_k$ for $k \geq 1$ has compact
$C^{2,\alpha}$ boundary for every $0<\alpha<1$. Moreover, for every $k \geq 1$
\begin{equation}\label{EL}
 H_{E^h_{k}}=-\frac{d_{E^h_{k-1}}}{h}
 \qquad\text{on $\partial E^h_{k}$ }\,.
\end{equation}
For every $p\in\partial E^h_{k}$, every $0<r\leq\gamma\sqrt h$, and every
finite-perimeter set $G$ satisfying
$G\triangle E^h_{k}\Subset B_r(p)$, one has
\begin{equation}\label{quasi}
 P(E^h_{k};B_r(p))
 \leq P(G;B_r(p))
 +\frac C{\sqrt h}|E^h_{k} \triangle G|\,.
\end{equation}
Finally, denoting $A_E$ the second fundamental form of a (regular) set $E$,  for every $\zeta\in C^1(\partial E^h_k)$ it holds 
\begin{equation}\label{stab}
 \int_{\partial E^h_{k}}
 \left(
 |\nabla_\tau\zeta|^2-|A_{E^h_{k}}|^2\zeta^2
 \right)\,d\mathcal H^n
 \geq
 -\frac1h\int_{\partial E^h_{k}}\zeta^2\,d\mathcal H^n\,.
\end{equation}

For every $T>0$ and every $0\leq s<t\leq T$,
\begin{equation}\label{discrete-time-holder}
 |E_t^h\triangle E_s^h|
 \leq CM\sqrt{|t-s|+h}+|E^h_h\triangle E_0|\,.
\end{equation}
The constant $C$ is independent of $h$, $s$ and $t$.

\label{def:Brakke}
    A (measurable) family of $n$-dimensional varifolds $\{V_t\}_{t\ge 0}$ is an $n$-dimensional Brakke flow if:
    \begin{itemize}
        \item[i)] For a.e. $t\ge 0$, $V_t$ is  integral, with   bounded first variation  absolutely continuous with respect to $\|V_t\|$ and generalized mean curvature vector $\mathbf{H}_t$;
        \item[ii)] for all $T> 0$ and compact $K\Subset \mathbb R^{n+1}$ it holds 
        \[
            \sup_{t\in [0,T]}\|V_t\|(K) <+\infty,\qquad \int_0^T\int |\mathbf H|^2 \,d\|V_t\|\,dt<+\infty\,; 
        \]
        \item[iii)] for all $0\le s<t<+\infty$ and all test function $\phi \in C^1_c(\mathbb R^{n+1}\times[0,+\infty);[0,+\infty))$ it holds 
        \begin{equation}\label{eq:def-Brakke} 
            \int \phi(\cdot,t)  d\|V_t \| - \int \phi(\cdot,s)  d\|V_s \| 
            \le \int_s^t
            \int\left( \partial_\tau\phi+\nabla\phi\cdot \mathbf{H}_\tau- \phi |\mathbf H_\tau|^2 \right) d\|V_\tau\|\, d\tau \,.
        \end{equation}
    \end{itemize}

\label{prop:AM}
    Let $F_j$ be $(\Lambda_j, R_j)$-minimizers in expanding domains $U_j \uparrow \mathbb R^{n+1}$ with
    \begin{equation} \label{hp:AM}
        \Lambda_j \to 0\,, \qquad R_j \to \infty \,,
    \end{equation}
    and assume uniform local perimeter bounds and $0 \in \partial^*F_j$. Then, up to a subsequence
    \begin{equation} \label{th:AM}
        \chi_{F_j} \to \chi_{F_\infty} \quad \mbox{in $L^1_{loc}$}\,,
    \end{equation}
    where $F_\infty$ is locally perimeter minimizing in $\mathbb R^{n+1}$. Furthermore, the perimeter measures converge locally, and, upon choosing representatives of $F_j$ and $F_\infty$ so that $\partial F_j=\operatorname{spt}|D\chi_{F_j}|$ and $\partial F_\infty=\operatorname{spt}|D\chi_{F_\infty}|$, the boundaries $\partial F_j$ converge locally in Hausdorff distance to $\partial F_\infty$, and $0 \in \partial F_\infty$. Finally, if $n \leq 6$, the boundaries $\partial F_j$ converge locally as $C^{1,\alpha}$ graphs to $\partial F_\infty$ near every point of $\partial F_\infty$.

\label{prop:curvature}
For $1\le n\le6$, every  iterate $E^h_k$ for $k\ge 1$ of \eqref{scheme} satisfies
\begin{equation*}
 \|A_{E^h_k}\|_{L^\infty(\partial E^h_k)}\le C_n/ \sqrt h\,.
\end{equation*}

\label{lem:reach}
Let $1\le n\le6$. Assume that $\partial E$ is a compact $C^2$ boundary such that there exist a radius $r_0 > 0$ and positive numbers $K,L$ so that for every $x\in\partial E$ the following holds in $B_{r_0}(x)$:
\begin{enumerate}
\item $|A_E|\le K/r_0$;
\item \eqref{density}--\eqref{area} hold for all $r\le r_0$, with fixed constants;
\item  the set $E$ is a $(L/r_0,  r_0)$-minimizer of the perimeter in $B_{r_0}(x)$.
\end{enumerate}
Then, there exists $c>0$ depending only on the constants above  such that
\[
 \operatorname{reach}(\partial E)\ge c r_0\,.
\]

Let $1\le n\le 6$, $h>0$. Every nonempty $E^h_k$, $k\ge 1$ satisfies
\begin{equation}\label{tubeest}
 \|A_{E^h_k}\|_\infty\le C/\sqrt h,
 \qquad \operatorname{reach}(\partial E^h_k)\ge c\sqrt h\,.
\end{equation}
In particular, $E^h_k$  satisfies the interior and exterior ball conditions with any radius smaller than $c\sqrt h$. The constants $C,c>0$ depend only on $n$.

\label{lem:tubecalc}
If $F$ satisfies \eqref{tubeest}, then for $|s|<a\sqrt h$, with fixed sufficiently small $a>0$, the map $\Psi(p,s)=p+s\nu_F(p)$ is injective and, setting $F_s=\{d_F<s\}$, it holds 
\begin{align}
 &J_\Psi(p,s)=\prod_{i=1}^n(1+s\kappa_i(p)),
 &|J_\Psi(p,s)-1|\le C|s|/\sqrt h\,,\label{jac}\\
 &P(F_s)\le(1+C|s|/\sqrt h)P(F),
 &|F_s\triangle F|\le C|s|P(F)\,,\label{parallel}\\
 &\nabla d_F(\Psi(p,s))=\nu_F(p),
 &\|D^2d_F\|\le C/\sqrt h\quad\hbox{in  } \{|d_F|< a \sqrt{h}\} \,.\label{hessd}
\end{align}

\label{lem:ROF}
Let $F\subset \mathbb T^{n+1}$. The (unique) minimizer
\[
 u=\mathop{\rm argmin}_{v\in BV\cap L^2}
 \left\{|Dv|(\mathbb T^{n+1})+\frac1{2h}\int|v-d_F|^2\right\}
\]
admits a calibration $z\in L^\infty(\mathbb T^{n+1};\mathbb R^{n+1})$ satisfying in $\mathbb T^{n+1}$
\begin{equation}\label{zconditions}
 |z|\le1,\qquad \operatorname{div} z=(u-d_F)/h,\qquad (z,Du)=|Du|,
\end{equation}
with the last equality intended in the sense of Radon measures. Moreover,
\begin{equation}\label{zbound}
 \operatorname{Lip}(u)\le1,\qquad \|u-d_F\|_\infty\le C\sqrt h,
 \qquad \|\operatorname{div} z\|_\infty\le C/\sqrt h.
\end{equation}

\label{lem:allmin}
Let $u,z$ be as above.  If $E$ is any minimizer of \eqref{scheme} with $F$ replacing $E^h_{k-1}$, then 
\begin{equation}\label{sign}
 \{u<0\}\subseteq E\subseteq \{u\le0\}, \text{ up to }\mathcal L^{n+1}\text{-negligible set}
\end{equation}
\begin{equation}\label{trace}
 [z,\nu_E]=1\quad\mathcal H^n\text{-a.e. on }\partial^*E\,,
\end{equation}
where \eqref{trace} is intended in the sense of normal traces.

For $k\ge 1$ it holds 
\begin{equation}\label{Ssum}
 0\le S^h_k\le P(E^h_{k-1})-P(E^h_{k})-\tfrac1hD(E^h_{k},E^h_{k-1}),
 \qquad \sum_{k=1}^KS^h_k\le M\,.
\end{equation}
For any compact set of finite perimeter $G\subset B_{1/4}$ and  $\varphi\in C_c^1$, $\varphi\ge0$, it holds 
\begin{equation}\label{local}
 P_\varphi(E^h_{k})-P_\varphi(G)
 \le-\frac{D_\varphi(E^h_{k},E^h_{k-1})}h+\frac{D_\varphi(G,E^h_{k-1})}h
     +\int(\chi_{E^h_{k}}-\chi_G)z\cdot\nabla\varphi\,.
\end{equation}

\label{lem:diss-bd}
For $h$ sufficiently small, depending on $b$, it holds 
\begin{equation}\label{endpointineq}
 -\frac{D_\varphi(E,F)}h
 \le h\delta P(E)[\varphi b]
 +\frac h2\int_{\partial F}\varphi|b\cdot\nu_F|^2d\mathcal H^n
 +C\bigl(D(E,F)+h^{3/2}P(F)\bigr)\,.
\end{equation}

Let $z$ be   a calibration for $E$ produced by Lemma \ref{lem:allmin}. For $0<r<a\sqrt h$, with $a$ as in Lemma \ref{lem:tubecalc}, it holds 
\begin{equation}\label{tubedefect}
 \int_{\{|d_F|<r\}}|z-\nabla d_{F}|^2
 \le C\left(rS +\frac{r^2}{\sqrt h}P(F)\right)\,.
\end{equation}
For $ R\ge 1$ with $hR<a\sqrt h$, and for $K,T$ so that $Kh\le T$,  it holds 
\begin{equation}\label{asum}
 \sum_{k=2}^{K}\int_{E^h_k\triangle E^h_{k-1}}
 |z^h_k-\nabla d_{E^h_{k-1}}|
 \le C_T\left(R^{-1}+h^{1/2}R^{1/2}+h^{1/4}R\right)\,,
\end{equation}
where $C_T$ depends on $M,T$.
Moreover,
\begin{equation}\label{eq:transp-term-old}
 \left|\int(\chi_E-\chi_F)z\cdot\nabla\varphi
           +h\delta P(E)[\nabla\varphi]\right|
 \le C\left(\int_{E \triangle F}|  z-\nabla d_F |+D(E,F)\right)\,.
\end{equation}

Fix $b\in C^2_c(\mathbb R^{n+1};\mathbb R^{n+1})$, $ \varphi\in C^2_c(\mathbb R^{n+1};\mathbb R_+)$. Then, for $h$ small enough  and  for  every  $k\ge2$  
\begin{equation}\label{dualineq}
\begin{split}
 P_\varphi(E^h_k)-P_\varphi(E^h_{k-1})\le h\Bigl[
 &\delta P(E^h_k)[\varphi b]+\delta P(E^h_{k-1})[\varphi b]
 -\delta P(E^h_k)[\nabla\varphi]\\
 &+\int_{\partial E^h_{k-1}}\varphi|b\cdot\nu_{E^h_{k-1}}|^2d\mathcal H^n\Bigr]+\rho^h_k\,,
\end{split}
\end{equation}
where $\rho^h_k\ge0$ can be chosen so that, for every $T>0$, it holds 
\begin{equation}\label{rho}
 \begin{split}
 \rho^h_k\le C\Bigl(&D(E^h_k,E^h_{k-1})+h^{3/2}P(E^h_{k-1})\\
 &+\int_{E^h_k\triangle E^h_{k-1}}|z^h_k-\nabla d_{E^h_{k-1}}|
 +\int_{\Phi_h(E^h_{k-1})\triangle E^h_{k-1}}
       |z^h_k-\nabla d_{E^h_{k-1}}|\Bigr)\,,\\
 \sum_{k=2}^{ [T/h]} \rho^h_k&\le C_T h^{1/8}\,.
 \end{split}
\end{equation}
The estimates are uniform in $[0,T]$ for  tests $\varphi,b$ with uniformly bounded  $C^2$  norms.

\label{thm:brakke}
Assume $1\le n\le6$. Let  $E_0\subset\mathbb R^{n+1}$ be a bounded set 
with finite perimeter with $|\partial E_0|=0$, and let
$E_t$ be a flat flow obtained as $L^1$ limit of $E^{h_j}_t$ as $h_j\to 0$.

Then, after passing to a further subsequence, there exists a measurable
family of  $n$-varifolds $\{V_t\}_{t\ge0}$ which are integral for a.e. $t\ge 0$ and   such that
\[
\begin{split}
  V_{E_t^{h_j}}dt
 &\rightharpoonup V_tdt\quad \text{as varifolds in space-time}\,, \\
 \|V_{E_t^{h_j}}\| &\rightharpoonup \|V_t\|  \quad \text{for every $t \geq 0$, as measures in space}\,,\\
 \{V_t\}_{t \geq 0} &\mbox{ is a Brakke flow with } V_0=V_{E_0}\,.
 \end{split}
\]
Moreover, we have:
\begin{itemize}
\item[(i)] \textit{Continuity at $t=0$}: as $t \to 0^+$
\begin{equation} \label{init-cont}
\begin{split}
    P(E_t) &\to P(E_0)\,,\\ 
    \|V_t\|(\mathbb R^{n+1}) &\to P(E_0)\,, \\
    \|V_t\| &\rightharpoonup |D\chi_{E_0}| \mbox{ as Radon measures}\,,\\
\|\|V_t\| - |D\chi_{E_t}| \|_{\mathrm{TV}} &\to 0\,.
    \end{split}
\end{equation}
    \item[(ii)]  \textit{Domination}: 
    \begin{equation}\label{domin}
    \|V_{E_t}\|=|D\chi_{E_t}|\le  \|V_t\|
 \quad\text{for every }t>0\,,
 \end{equation}
\item[(iii)] \textit{$\mathrm{mod}(2)$ compatibility}:
\begin{equation} \label{mod2-equiv}
    [V_t] = \partial\llbracket E_t\rrbracket \quad \mathrm{mod}(2) \qquad \text{for a.e. $ t > 0$}\,.
\end{equation}
\end{itemize}
Finally, the dissipation inequality holds:
\begin{equation} \label{eq:dissipation}
    \|V_t\|(\mathbb R^{n+1}) + \int_0^t \int |\mathbf H_\tau|^2 \, d\|V_\tau\|\,d\tau \leq  P(E_0) \qquad \text{for every $t \geq 0$}\,.
\end{equation}

We observe explicitly that \eqref{mod2-equiv} is equivalent to the fact that for a.e. $t > 0$ there exists an integral varifold $Z_t$ so that 
    \begin{equation} \label{mod2-equiv-2}
        V_t = V_{E_t} + 2Z_t\,.
    \end{equation}
    In particular, setting $V_t = \mathbf{var}(M_t,\theta_t)$, we have that
    \begin{equation} \label{eq:parity}
        \theta_t (x) \begin{cases}
            \mbox{is an odd integer} & \mathcal H^n\mbox{-a.e. } x \in \partial^*E_t  \\
            \mbox{is an even integer} & \mathcal H^n\mbox{-a.e. } x \in M_t \setminus \partial^*E_t \,. \\
        \end{cases}
    \end{equation}

\label{thm:L2-to-BV}
Let $\{V_t\}_{t\in[0,T)}$ be an  $L^2$-flow in
$\mathbb{R}^{n+1}$ with space-time measure $d\mu=d\|V_t\|dt$ and velocity $v$, and let $\{E_t\}_{t\in [0,T)}$ be a   family of sets of finite perimeter satisfying
\[
    |D\chi_{E_t}|
    \leq \|V_t\|, \qquad \text{for every }t\in [0,T)\,.
\]
Define the corresponding space-time tube $\mathcal E:= \{(x,t)\in\mathbb{R}^{n+1}\times[0,T):
      x\in E_t\}$.
Assume that
\begin{itemize}
    \item[i)] it holds  $\Theta^{*n}(\|V_t\|,x)
    :=
    \limsup_{r\searrow0}
    \frac{\|V_t\|(B_r(x))}{\omega_nr^n}
    <\infty$ for a.e. $t$ and $\|V_t\|$-a.e. $x$;
    \item[ii)] it holds $
    |D_{x,t}\chi_{\mathcal E}|\ll \|V_t\|dt
    $ in $
    \mathbb{R}^{n+1}\times(0,T)$;
    \item[iii)] the tube $\mathcal E$ satisfies  $
    \chi_{\mathcal E}    \in
    C_{\mathrm{loc}}^{1/2}
    \bigl([0,T);L^1(\mathbb{R}^{n+1})\bigr)
    \cap
    BV_{\mathrm{loc}}
    \bigl(\mathbb{R}^{n+1}\times[0,T)\bigr)$.
\end{itemize}
Then, the velocity $v$ belongs to $L^2_{loc}(|D\chi_{E_t} | dt ;\mathbb R^{n+1})$, and for every 
$0\leq t_1<t_2<T$ and every
$\phi\in C_c^1(\mathbb{R}^{n+1}\times[0,T))$ it holds 
\begin{equation*}
    \int_{E_{t_2}}\phi(x,t_2)\,dx
    -
    \int_{E_{t_1}}\phi(x,t_1)\,dx =
    \int_{t_1}^{t_2}
    \int_{E_t}
    \partial_t\phi\,dx\,dt
    +
    \int_{t_1}^{t_2}
    \int_{\partial^*E_t}
    \phi\,v\cdot\nu_{E_t}
    \,d\mathcal H^n\,dt
\end{equation*}

\label{thm:main}
    Assume $1\le n\le 6$. Let $E_0\subseteq \mathbb R^{n+1} $ be a bounded set with finite perimeter and $|\partial E_0|=0$, and consider a flat flow $E_t $ starting from $E_0$. Let $V_t$ be the integral Brakke flow of Theorem \ref{thm:brakke}. Then, $\left( \{V_t\}_{t \geq 0}, \{E_t\}_{t \geq 0} \right)$ is a generalized BV flow: for every $0\leq t_1<t_2<+\infty$ and every
    $\phi\in C_c^1(\mathbb{R}^{n+1}\times[0,\infty))$ it holds 
    \begin{equation}
    \int_{E_{t_2}}\phi(x,t_2)\,dx
    -
    \int_{E_{t_1}}\phi(x,t_1)\,dx =
    \int_{t_1}^{t_2}
    \int_{E_t}
    \partial_t\phi\,dx\,dt
    +
    \int_{t_1}^{t_2}
    \int_{\partial^*E_t}
    \phi\,\mathbf H_{t}\cdot\nu_{E_t}
    \,d\mathcal H^n\,dt
    \label{eq:BV-gener}.
\end{equation}

Notice that, as a consequence of Theorem \ref{thm:main}, we have the explicit representation
\begin{equation} \label{eq:time-derivative}
    D_t\chi_{\mathcal E} = - \mathbf H \cdot \frac{d (D\chi_{E_t})}{d\|V_t\|} \, d\|V_t\|dt \qquad \mbox{in the sense of space-time measures}\,,
\end{equation}
that is the limit $w$ in the proof of Theorem \ref{thm:main} admits the explicit characterization $w = -\mathbf{H} \cdot \frac{d (D\chi_{E_t})}{d\|V_t\|}$.

\label{cor:extinction}
    Under the same assumptions of Theorem \ref{thm:main}, setting $a(t):= \|V_t\|(\mathbb R^{n+1})$, it holds
    \begin{equation} \label{eq:holder-sharp}
    |E_t\triangle E_s|
    \le\left[\frac{t-s}{2}\bigl(a(s)^2-a(t)^2\bigr)\right]^{1/2}
    \qquad(0\le s<t).
\end{equation}
    In particular, if the extinction time $T_\star$ is defined by
    \[
    T_\star := \sup\{t \geq 0 \, \colon \, \|V_t\| \neq 0\}\,.
    \]
    then, if $|E_0|>0$ it holds
    \begin{equation} \label{eq:extinction}
        T_\star \geq 2 \left ( \frac{|E_0|}{P(E_0)} \right)^2\,.
    \end{equation}
